import sys
import os
import json
import datetime

def parse_iso_week(wk_str):
    if not wk_str or wk_str == '~':
        return None
    try:
        # Format: YYYY-Www-D
        parts = wk_str.split('-')
        year = int(parts[0])
        week = int(parts[2].split('W')[1])
        day = int(parts[2].split('-')[1])
        # datetime.strptime handles ISO week format %G-W%V-%u
        # %G is ISO year, %V is ISO week, %u is day of week (1-7)
        return datetime.datetime.strptime(f"{year}-W{week:02d}-{day}", "%G-W%V-%u").strftime("%Y-%m-%d")
    except:
        return None

def load_tsv(filepath):
    data = {}
    if not os.path.exists(filepath):
        return data
    with open(filepath, 'r') as f:
        lines = f.readlines()

    header_found = False
    rows = []
    for line in lines:
        if line.startswith('#'):
            continue
        parts = line.strip().split('\t')
        if not parts or parts[0] == '':
            continue
        if parts[0] == 'attribute':
            rows.append(parts)
            header_found = True
        elif header_found:
            rows.append(parts)

    if not rows:
        return data

    # rows[0] is ['attribute', 'rec.01', 'rec.02', ...]
    # rows[1:] are the attributes
    num_cols = len(rows[0])
    for i in range(1, num_cols):
        rec_id = rows[0][i]
        rec_data = {}
        for r in range(1, len(rows)):
            attr = rows[r][0]
            val = rows[r][i]
            if val != '~':
                rec_data[attr] = val
        data[rec_id] = rec_data
    return data

def main():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]

    invoices = load_tsv(os.path.join(dir_path, 'invoices.tsv'))
    payments = load_tsv(os.path.join(dir_path, 'payments.tsv'))
