    receipts = load_tsv(os.path.join(dir_path, 'receipts.tsv'))
    requisitions = load_tsv(os.path.join(dir_path, 'requisitions.tsv'))
    warehouse_scans = load_tsv(os.path.join(dir_path, 'warehouse_scans.tsv'))

    # Pre-index data by order.key for easier lookup
    # Since multiple records might have same order.key in some files, 
    # but the prompt implies a 1:1 or fallback logic.
    # We'll build maps: order_key -> {attr: value}

    def build_map(dataset):
        mapping = {}
        for rec in dataset.values():
            key = rec.get('order.key')
            if key:
                mapping[key] = rec
        return mapping

    inv_map = build_map(invoices)
    pay_map = build_map(payments)
    po_map = build_map(purchase_orders)
    rec_map = build_map(receipts)
