    results = {}

    pairs = []
    for i in range(40101, 40117):
        pairs.append(f"pa.three_way_match::PO-{i:04d}")
    for i in range(40101, 40117):
        pairs.append(f"pa.paid_in_window::PO-{i:04d}")

    for pair_id in pairs:
        rule, po_key = pair_id.split('::')
        res_obj = {}

        if rule == 'pa.three_way_match':
            # invoice amount
            if po_key in inv_map:
