            else:
                res_obj['invoice amount'] = "ABSENT"

            # order amount
            if po_key in po_map:
                res_obj['order amount'] = ["{}".format(po_map[po_key].get('order.commit.usd', '')), 'purchase_orders']
            else:
                res_obj['order amount'] = "ABSENT"

            # quantity received
            if po_key in rec_map:
                res_obj['quantity received'] = ["{}".format(rec_map[po_key].get('goodsin.units', '')), 'receipts']
            else:
                res_obj['quantity received'] = "ABSENT"

            # quantity invoiced
            if po_key in inv_map:
                res_obj['quantity invoiced'] = ["{}".format(inv_map[po_key].get('bill.qty.units', '')), 'invoices']
            else:
                res_obj['quantity invoiced'] = "ABSENT"

        elif rule == 'pa.paid_in_window':
            # goods received
            goods_received = "ABSENT"
            if po_key in rec_map and 'goodsin.day.wk' in rec_map[po_key]:
