import sys
import os
import json
import re
from datetime import datetime

def parse_date(date_str):
    if not date_str:
        return None
    # Remove day of week if present (e.g., "Mon., ")
    date_str = re.sub(r'^[A-Za-z]+,\s*', '', date_str)
    # Handle abbreviated months
    months = {
        'Jan.': 'Jan', 'Feb.': 'Feb', 'Mar.': 'Mar', 'Apr.': 'Apr',
        'May': 'May', 'Jun.': 'Jun', 'Jul.': 'Jul', 'Aug.': 'Aug',
        'Sep.': 'Sep', 'Oct.': 'Oct', 'Nov.': 'Nov', 'Dec.': 'Dec'
    }
    for abbr, full in months.items():
        date_str = date_str.replace(abbr, full)

    # Try common formats
    formats = ['%b %d, %Y', '%B %d, %Y']
    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    return None

def parse_amount(amt_str):
    if not amt_str:
        return None
    # Remove currency and commas
    clean = re.sub(r'[^\d.]', '', amt_str)
    try:
        return f"{float(clean):.2f}"
    except ValueError:
        return None

def parse_units(unit_str):
    if not unit_str:
        return None
    clean = re.sub(r'[^\d]', '', unit_str)
    return clean if clean else None

def extract_data(directory):
    files = {}
    for filename in os.listdir(directory):
        path = os.path.join(directory, filename)
        if os.path.isfile(path):
            with open(path, 'r', encoding='utf-8') as f:
                files[filename] = f.read()

    # Data structures
    # invoices[po] = {amount, units, deadline}
    invoices = {}
    # purchase_orders[po] = {amount}
    pos = {}
    # receipts[po] = {units, date}
    receipts = {}
    # warehouse_scans[po] = {date}
    scans = {}
    # payments[po] = {date}
    payments = {}

    # Parse Invoices
    if 'invoices.html' in files:
        content = files['invoices.html']
        sheets = re.findall(r'<article class="sheet".*?</table>', content, re.DOTALL)
        for sheet in sheets:
            po_match = re.search(r'Procurement reference</th><td><strong>(PO-\d+)</strong>', sheet)
            if po_match:
                po = po_match.group(1)
                amt_match = re.search(r'Invoice grand total</th><td>USD ([\d,.]+)</td>', sheet)
                units_match = re.search(r'Units charged</th><td>(\d+) pcs</td>', sheet)
                deadline_match = re.search(r'Payment deadline</th><td>(.*?)</td>', sheet)

                invoices[po] = {
                    'invoice amount': [parse_amount(amt_match.group(1)) if amt_match else None, 'invoices.html'],
                    'quantity invoiced': [parse_units(units_match.group(1)) if units_match else None, 'invoices.html'],
                    'payment due': [parse_date(deadline_match.group(1)) if deadline_match else None, 'invoices.html']
                }

    # Parse Purchase Orders
    if 'purchase_orders.html' in files:
        content = files['purchase_orders.html']
        sheets = re.findall(r'<article class="sheet".*?</table>', content, re.DOTALL)
        for sheet in sheets:
            po_match = re.search(r'Procurement reference</th><td><strong>(PO-\d+)</strong>', sheet)
            if po_match:
                po = po_match.group(1)
                amt_match = re.search(r'Total order value</th><td[^>]*>USD ([\d,.]+)</td>', sheet)
                if amt_match:
                    pos[po] = {'order amount': [parse_amount(amt_match.group(1)), 'purchase_orders.html']}

    # Parse Receipts
    if 'receipts.html' in files:
        content = files['receipts.html']
        sheets = re.findall(r'<article class="sheet".*?</table>', content, re.DOTALL)
        for sheet in sheets:
            po_match = re.search(r'Procurement reference</th><td><strong>(PO-\d+)</strong>', sheet)
            if po_match:
                po = po_match.group(1)
                units_match = re.search(r'Units counted on delivery</th><td>(\d+) pcs</td>', sheet)
                date_match = re.search(r'Delivery booked</th><td>(.*?)</td>', sheet)
                if units_match or date_match:
                    receipts[po] = {
                        'quantity received': [parse_units(units_match.group(1)) if units_match else None, 'receipts.html'],
                        'goods received': [parse_date(date_match.group(1)) if date_match else None, 'receipts.html']
                    }

    # Parse Warehouse Scans
    if 'warehouse_scans.html' in files:
        content = files['warehouse_scans.html']
        sheets = re.findall(r'<article class="sheet".*?</table>', content, re.DOTALL)
        for sheet in sheets:
            po_match = re.search(r'Procurement reference</th><td><strong>(PO-\d+)</strong>', sheet)
            if po_match:
                po = po_match.group(1)
                date_match = re.search(r'Dock scanner stamp</th><td>(.*?)</td>', sheet)
                if date_match:
                    scans[po] = {'goods received': [parse_date(date_match.group(1)), 'warehouse_scans.html']}

    # Parse Payments
    if 'payments.html' in files:
        content = files['payments.html']
        sheets = re.findall(r'<article class="sheet".*?</table>', content, re.DOTALL)
        for sheet in sheets:
            po_match = re.search(r'Procurement reference</th><td><strong>(PO-\d+)</strong>', sheet)
            if po_match:
                po = po_match.group(1)
                date_match = re.search(r'Funds released</th><td>(.*?)</td>', sheet)
                if date_match:
                    payments[po] = {'payment date': [parse_date(date_match.group(1)), 'payments.html']}

    return invoices, pos, receipts, scans, payments

def solve():
