from datetime import datetime

def parse_date(date_str):
    if not date_str:
        return None
    # Clean up common date formats found in the text
    date_str = date_str.strip().lower()
    # Remove ordinal suffixes (st, nd, rd, th) from days
    date_str = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', date_str)

    formats = [
        "%b %d %Y",      # 15th Feb 2026 -> 15 feb 2026
        "%d %b %Y",      # 15 Feb 2026
        "%B %d, %Y",     # February 10th, 2026 -> february 10, 2026
        "%b %d, %Y",     # Mar 24, 2026
        "%d %B %Y",      # 24 March 2026
        "%B %d %Y",      # March 24 2026
        "%m/%d/%Y",      # Not expected but safe
        "%Y-%m-%d"       # Standard
    ]

    # Handle "April 2nd, 2026" style
    # The regex above handles the 'nd'

    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    return None

def parse_amount(amt_str):
    if not amt_str:
        return None
    # Remove currency symbols and commas
    clean = re.sub(r'[^\d.]', '', amt_str)
    try:
        return float(clean)
    except ValueError:
        return None

