from datetime import datetime

def parse_date(date_str):
    if not date_str:
        return None
    # Try various formats found in the text
    formats = [
        "%Y-%m-%d",
        "%d %b %Y",
        "%d %B %Y",
        "%d %b %y",
        "%B %d, %Y",
        "%b %d, %Y",
        "%d %b %Y %H:%M:%S %z",
        "%d %B %Y %H:%M:%S %z",
        "%d %b %Y %H:%M:%S %Z",
    ]
    # Clean up common patterns like "29th Jul 2026" -> "29 Jul 2026"
    date_str = re.sub(r'(\d+)(st|nd|rd|th)', r'\1', date_str)

    for fmt in formats:
        try:
            return datetime.strptime(date_str.strip(), fmt)
        except ValueError:
            continue
    return None

def parse_amount(amt_str):
    if not amt_str:
        return None
    # Remove currency symbols and commas
    clean = re.sub(r'[^\d.]', '', amt_str.replace(',', ''))
    try:
        return float(clean)
    except ValueError:
        return None

def parse_int(int_str):
