    # Find the header line (the one starting with 'attribute')
    header_idx = -1
    for i, line in enumerate(lines):
        if line.startswith('attribute'):
            header_idx = i
            break

    if header_idx == -1:
        return data

    # Parse the header to get column names (rec.01, rec.02, etc.)
    header_parts = lines[header_idx].strip().split('\t')
    cols = header_parts[1:] # Skip 'attribute'

    # Parse the rows
