            continue
        rows.append(line.strip().split('\t'))

    # Transpose: rows are attributes, cols are records
    # We want: data[attribute][order_key] = value
    # But the rule says: "each COLUMN after the first is one record"
    # So we iterate through columns.

    # First, let's build a map of attribute -> list of values
