import sys
import os
import json
import re
from datetime import datetime

def parse_date(date_str):
    # Handles formats like "Sat., March 21, 2026" or "Sun., Jan. 11, 2026"
    # Remove day of week and extra dots
    clean = re.sub(r'^[A-Za-z]+,\s*', '', date_str)
    clean = clean.replace('.', '')
    try:
        return datetime.strptime(clean, '%B %d, %Y').strftime('%Y-%m-%d')
    except ValueError:
        try:
            return datetime.strptime(clean, '%b %d, %Y').strftime('%Y-%m-%d')
        except ValueError:
            return None

def parse_amount(amt_str):
    # Extracts decimal from "USD 30,000.00"
    match = re.search(r'(\d{1,3}(?:,\d{3})*(?:\.\d{2}))', amt_str)
    if match:
        return match.group(1).replace(',', '')
    return None

def parse_units(unit_str):
    # Extracts integer from "286 pcs"
    match = re.search(r'(\d+)', unit_str)
    if match:
        return match.group(1)
    return None

def extract_data(directory):
    files = {}
    for filename in os.listdir(directory):
        path = os.path.join(directory, filename)
