import os
import sys
import json
import re
from datetime import datetime

def parse_date(date_str):
    if not date_str or "left blank" in date_str:
        return None
    # Remove day of week if present (e.g., "Sat., ")
    date_str = re.sub(r'^[A-Za-z]+,\s+', '', date_str)
    # Handle abbreviated months (e.g., "Feb.")
    date_str = date_str.replace('.', '')
    formats = ['%B %d, %Y', '%b %d, %Y', '%B %d %Y', '%b %d %Y']
    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    return None

def parse_amount(amt_str):
    if not amt_str:
        return None
    # Extract numeric part: "USD 132,000.00" -> "132000.00"
    match = re.search(r'[\d,]+\.\d{2}', amt_str)
    if match:
        return match.group().replace(',', '')
    return None

def parse_units(unit_str):
    if not unit_str:
        return None
    match = re.search(r'(\d+)\s+pcs', unit_str)
    if match:
        return int(match.group(1))
    return None

def extract_data(directory):
