import sys
import os
import json
import re
from datetime import date, timedelta

def parse_sql(content):
    """
    A simple parser for the provided SQL format.
    Extracts table names and their corresponding rows as lists of values.
    """
    tables = {}
    current_table = None

    # Split by CREATE TABLE and INSERT INTO
    lines = content.split('\n')
    for line in lines:
        line = line.strip()
        if not line:
            continue

        create_match = re.match(r'CREATE TABLE (\w+) \(', line)
        if create_match:
            current_table = create_match.group(1)
            tables[current_table] = []
            continue

        insert_match = re.match(r'INSERT INTO (\w+) \(.*\) VALUES\s*(.*);', line, re.IGNORECASE)
        if insert_match:
            table_name = insert_match.group(1)
            values_part = insert_match.group(2)

            # Handle multiple VALUES tuples in one INSERT statement if they exist
            # The format shows (row, 'val', ...) VALUES (...), (...);
            # We split by '), (' but need to be careful with commas inside strings.
            # Given the strict format, we can split by the pattern of closing and opening parens.
            tuples = re.findall(r'\((.*?)\)', values_part)

            for t in tuples:
                # Split by comma, but only if not inside single quotes
                parts = []
                current_part = []
                in_quotes = False
                for char in t:
                    if char == "'" and (not current_part or current_part[-1] != "\\"):
                        in_quotes = not in_quotes
                        current_part.append(char)
                    elif char == "," and not in_quotes:
                        parts.append("".join(current_part).strip())
                        current_part = []
                    else:
                        current_part.append(char)
                parts.append("".join(current_part).strip())

                # Clean up parts: remove quotes from strings, handle NULL
                cleaned_parts = []
                for p in parts:
                    if p.upper() == 'NULL':
                        cleaned_parts.append(None)
                    elif p.startswith("'") and p.endswith("'"):
                        cleaned_parts.append(p[1:-1])
                    else:
                        cleaned_parts.append(p)

                if table_name not in tables:
                    tables[table_name] = []
                tables[table_name].append(cleaned_parts)

    return tables

def epd_to_date(epd):
    if epd is None:
        return None
    return (date(1970, 1, 1) + timedelta(days=int(epd))).isoformat()

def solve():
    if len(sys.argv) < 2:
        return

    dir_path = sys.argv[1]
    files = {
        'invoices': 'invoices.sql',
        'payments': 'payments.sql',
        'purchase_orders': 'purchase_orders.sql',
        'receipts': 'receipts.sql',
        'requisitions': 'requisitions.sql',
        'warehouse_scans': 'warehouse_scans.sql'
    }

    data = {}
    for key, filename in files.items():
        path = os.path.join(dir_path, filename)
        if os.path.exists(path):
            with open(path, 'r') as f:
                data[key] = parse_sql(f.read())
        else:
            data[key] = {}

    # Helper to get data from tables
    # invoices: row_seq, ord_code, pay_deadline_epd, billed_unit_ct, billed_cents
    # payments: row_seq, ord_code, funds_out_epd
    # purchase_orders: row_seq, ord_code, commit_cents
    # receipts: row_seq, ord_code, dock_unit_ct, goods_in_epd
    # warehouse_scans: row_seq, ord_code, scanner_hit_epd

    results = {}

    pairs = []
    # Generate all requested pairs
    for po_id in [f"PO-{i:04d}" for i in range(41001, 41017)]:
        pairs.append(f"pa.three_way_match::{po_id}")
    for po_id in [f"PO-{i:04d}" for i in range(41001, 41017)]:
        pairs.append(f"pa.paid_in_window::{po_id}")

    for pair_id in pairs:
        rule, po_id = pair_id.split("::")
        results[pair_id] = {}

        if rule == "pa.three_way_match":
            # invoice amount (USD)
            inv_amt = None
            inv_doc = None
            for row in data['invoices'].get('supplier_bill', []):
                if row[1] == po_id and row[4] is not None:
                    inv_amt = f"{float(row[4])/100:.2f}"
                    inv_doc = "invoices.sql"
                    break
            results[pair_id]["invoice amount"] = [inv_amt, inv_doc] if inv_amt else "ABSENT"

            # order amount (USD)
            ord_amt = None
            ord_doc = None
            for row in data['purchase_orders'].get('order_commitment', []):
                if row[1] == po_id and row[2] is not None:
                    ord_amt = f"{float(row[2])/100:.2f}"
                    ord_doc = "purchase_orders.sql"
                    break
            results[pair_id]["order amount"] = [ord_amt, ord_doc] if ord_amt else "ABSENT"

            # quantity received (units)
            qty_rec = None
            qty_rec_doc = None
            for row in data['receipts'].get('goods_in_note', []):
                if row[1] == po_id and row[2] is not None:
                    qty_rec = str(row[2])
                    qty_rec_doc = "receipts.sql"
                    break
            results[pair_id]["quantity received"] = [qty_rec, qty_rec_doc] if qty_rec else "ABSENT"

            # quantity invoiced (units)
            qty_inv = None
            qty_inv_doc = None
            for row in data['invoices'].get('supplier_bill', []):
                if row[1] == po_id and row[3] is not None:
                    qty_inv = str(row[3])
                    qty_inv_doc = "invoices.sql"
                    break
            results[pair_id]["quantity invoiced"] = [qty_inv, qty_inv_doc] if qty_inv else "ABSENT"

        elif rule == "pa.paid_in_window":
            # goods received (date)
            gr_date = None
            gr_doc = None
            for row in data['receipts'].get('goods_in_note', []):
                if row[1] == po_id and row[3] is not None:
                    gr_date = epd_to_date(row[3])
                    gr_doc = "receipts.sql"
                    break
            if not gr_date:
                for row in data['warehouse_scans'].get('dock_scanner_event', []):
                    if row[1] == po_id and row[2] is not None:
                        gr_date = epd_to_date(row[2])
                        gr_doc = "warehouse_scans.sql"
                        break
            results[pair_id]["goods received"] = [gr_date, gr_doc] if gr_date else "ABSENT"

            # payment date (date)
            pay_date = None
            pay_doc = None
            for row in data['payments'].get('remittance', []):
                if row[1] == po_id and row[2] is not None:
                    pay_date = epd_to_date(row[2])
                    pay_doc = "payments.sql"
                    break
            results[pair_id]["payment date"] = [pay_date, pay_doc] if pay_date else "ABSENT"

            # payment due (date)
            due_date = None
            due_doc = None
            for row in data['invoices'].get('supplier_bill', []):
                if row[1] == po_id and row[2] is not None:
                    due_date = epd_to_date(row[2])
                    due_doc = "invoices.sql"
                    break
            results[pair_id]["payment due"] = [due_date, due_doc] if due_date else "ABSENT"

    print(json.dumps(results))

if __name__ == "__main__":
    solve()
